using namespace std;
long long f(vector<vector<long long>> &dp, vector<int> &nums, int index, int k) {
    if (k == 0) return 0;  // If we've chosen k elements, return 0.
    if (index < 0) return LLONG_MAX;  // If out of bounds, return a large number.

    if (dp[index][k] != -1) return dp[index][k];

    // Pick the current house
    long long pick = max((long long)nums[index], f(dp, nums, index - 2, k - 1));

    // Skip the current house
    long long notPick = f(dp, nums, index - 1, k);

    return dp[index][k] = min(pick, notPick);
}
int minCapability(vector<int>& nums, int k) {
    int n = nums.size();
        vector<vector<long long>> dp(n, vector<long long>(k + 1, -1));
        return f(dp, nums, n - 1, k);
    
}
